// Subscribe once, for example in the form constructor:
lblStatus.Click += lblStatus_Click;

private void lblStatus_Click(object sender, EventArgs e)
{
    lblStatus.Text = "You clicked the status label.";
}

// Subscribe once, for example in the form constructor:
lblStatus.TextChanged += lblStatus_TextChanged;

private void lblStatus_TextChanged(object sender, EventArgs e)
{
    btnRetry.Enabled = lblStatus.Text.StartsWith("Error");
}

// Subscribe once, for example in the form constructor:
lblStatus.TextAlignChanged += lblStatus_TextAlignChanged;

private void lblStatus_TextAlignChanged(object sender, EventArgs e)
{
    MessageBox.Show("Alignment is now " + lblStatus.TextAlign);
}

// Subscribe once, for example in the form constructor:
btnSave.Click += btnSave_Click;

private void btnSave_Click(object sender, EventArgs e)
{
    string name = txtName.Text.Trim();
    if (name.Length == 0)
    {
        MessageBox.Show("Please enter a name.");
        return;
    }
    MessageBox.Show("Hello, " + name + "!");
}

// Subscribe once, for example in the form constructor:
btnSave.MouseEnter += btnSave_MouseEnter;

private void btnSave_MouseEnter(object sender, EventArgs e)
{
    btnSave.BackColor = Color.LightSkyBlue;
}

// Subscribe once, for example in the form constructor:
btnSave.MouseLeave += btnSave_MouseLeave;

private void btnSave_MouseLeave(object sender, EventArgs e)
{
    btnSave.BackColor = SystemColors.Control;
}

// Subscribe once, for example in the form constructor:
btnSave.EnabledChanged += btnSave_EnabledChanged;

private void btnSave_EnabledChanged(object sender, EventArgs e)
{
    btnSave.Text = btnSave.Enabled ? "Save" : "Saving...";
}

// Subscribe once, for example in the form constructor:
txtEmail.TextChanged += txtEmail_TextChanged;

private void txtEmail_TextChanged(object sender, EventArgs e)
{
    btnSearch.Enabled = txtEmail.Text.Length > 0;
}

// Subscribe once, for example in the form constructor:
txtEmail.KeyPress += txtEmail_KeyPress;

private void txtEmail_KeyPress(object sender, KeyPressEventArgs e)
{
    if (!char.IsControl(e.KeyChar) && !char.IsDigit(e.KeyChar))
    {
        e.Handled = true; // ignore anything that is not a digit
    }
}

// Subscribe once, for example in the form constructor:
txtEmail.KeyDown += txtEmail_KeyDown;

private void txtEmail_KeyDown(object sender, KeyEventArgs e)
{
    if (e.KeyCode == Keys.Enter)
    {
        e.SuppressKeyPress = true; // no beep sound
        btnSearch.PerformClick();
    }
}

// Subscribe once, for example in the form constructor:
txtEmail.Validating += txtEmail_Validating;

private void txtEmail_Validating(object sender, CancelEventArgs e)
{
    if (string.IsNullOrWhiteSpace(txtEmail.Text))
    {
        e.Cancel = true;
        errorProvider1.SetError(txtEmail, "E-mail is required.");
    }
    else
    {
        errorProvider1.SetError(txtEmail, "");
    }
}

