private void rtbNotes_LinkClicked(object sender, LinkClickedEventArgs e)
{
    // requires: using System.Diagnostics;
    Process.Start(new ProcessStartInfo(e.LinkText) { UseShellExecute = true });
}

// Subscribe once, for example in the form constructor:
mtbPhone.MaskInputRejected += mtbPhone_MaskInputRejected;

private void mtbPhone_MaskInputRejected(object sender, MaskInputRejectedEventArgs e)
{
    lblHint.Text = "Not allowed here: " + e.RejectionHint;
}

// Subscribe once, for example in the form constructor:
mtbPhone.TypeValidationCompleted += mtbPhone_TypeValidationCompleted;
mtbPhone.ValidatingType = typeof(DateTime); // needed for this event to convert the text

private void mtbPhone_TypeValidationCompleted(object sender, TypeValidationEventArgs e)
