private void mtbPhone_TextChanged(object sender, EventArgs e)
{
    btnSave.Enabled = mtbPhone.MaskCompleted;
}

// Subscribe once, for example in the form constructor:
chkOptions.CheckedChanged += chkOptions_CheckedChanged;

private void chkOptions_CheckedChanged(object sender, EventArgs e)
{
    btnContinue.Enabled = chkOptions.Checked;
}

// Subscribe once, for example in the form constructor:
chkOptions.CheckStateChanged += chkOptions_CheckStateChanged;

private void chkOptions_CheckStateChanged(object sender, EventArgs e)
{
    switch (chkOptions.CheckState)
    {
        case CheckState.Checked:       lblState.Text = "All";  break;
        case CheckState.Unchecked:     lblState.Text = "None"; break;
        case CheckState.Indeterminate: lblState.Text = "Some"; break;
    }
}

