// Subscribe once, for example in the form constructor:
picPhoto.Click += picPhoto_Click;

private void picPhoto_Click(object sender, EventArgs e)
{
    picPhoto.BorderStyle = picPhoto.BorderStyle == BorderStyle.None
        ? BorderStyle.FixedSingle
        : BorderStyle.None;
}

// Subscribe once, for example in the form constructor:
picPhoto.LoadCompleted += picPhoto_LoadCompleted;
picPhoto.LoadAsync("https://example.com/photo.jpg"); // starts the download

private void picPhoto_LoadCompleted(object sender, AsyncCompletedEventArgs e)
{
    if (e.Error != null)
    {
        lblStatus.Text = "Could not load the picture: " + e.Error.Message;
    }
    else if (!e.Cancelled)
    {
        lblStatus.Text = "Picture loaded.";
    }
}

