}

// Subscribe once, for example in the form constructor:
toolTip1.Draw += toolTip1_Draw;
toolTip1.OwnerDraw = true; // required for the Draw event

private void toolTip1_Draw(object sender, DrawToolTipEventArgs e)
{
    e.DrawBackground();
    e.DrawBorder();
    e.DrawText();
}
